{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "The proposed AUD 4.8 million cap, AUD 25,000 de minimis, AUD 250,000 deductible basket and 18-month notification period significantly restrict recovery."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Negotiate a lower threshold and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, including coverage through an audit cycle."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Give title, ownership, authority and capacity warranties a separate cap up to the purchase price and a substantially longer claim period"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly preserve remedies for fraud and fraudulent misrepresentation"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject disclosure merely because material exists somewhere in the data room or public records."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit any knowledge exclusion to the actual knowledge of specifically named Buyer individuals"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make Completion conditional on receipt of a valid written consent and satisfaction or effective waiver of all associated conditions"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require a binding payout statement and irrevocable discharge/release arrangements effective at Completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Specify Seller funding or an appropriate debt-like/price adjustment, and show the payment and funding route in the funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the specific indemnity to cover losses and costs arising from the ownership/transfer defect, not merely payment of the fee"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PARTIAL",
      "evidence": "consider a tailored indemnity or other protection once facts are better known"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Include any appropriate liability or debt-like adjustment under the agreed mechanism, avoiding double recovery; do not automatically deduct the full amount."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Map each limitation and remedy clause against every claim category and make the agreed exceptions express."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "The register supports the stated 100% holding but is not a complete verification of title or absence of encumbrances."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek a separate pre-Completion tax covenant or indemnity"
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

